import Modal from '~/components/common/Modal/Modal';
import { useModal } from '~/hooks/useModal';
import * as S from './ScheduleEditModal.styled';
import Button from '~/components/common/Button/Button';
import { CloseIcon } from '~/assets/svg';
import Input from '~/components/common/Input/Input';
import Text from '~/components/common/Text/Text';
import { useScheduleEditModal } from '~/hooks/schedule/useScheduleEditModal';
import type { Schedule } from '~/types/schedule';
import TeamBadge from '~/components/team/TeamBadge/TeamBadge';
import TimeTableMenu from '~/components/team_calendar/TimeTableMenu/TimeTableMenu';
import { useTeamPlace } from '~/hooks/useTeamPlace';
import type { CalendarSize } from '~/types/size';
import { getIsMobile } from '~/utils/getIsMobile';
import Switch from '~/components/common/Switch/Switch';
import theme from '~/styles/theme';
import Svg from '~/components/common/Svg/Svg';
import { SCHEDULE_DESCRIPTION_MAX_LENGTH } from '~/constants/calendar';

interface ScheduleEditModalProps {
  calendarSize?: CalendarSize;
  scheduleId: Schedule['id'];
  initialSchedule?: Schedule;
}

const ScheduleEditModal = (props: ScheduleEditModalProps) => {
  const { scheduleId, initialSchedule, calendarSize = 'md' } = props;
  const isMobile = getIsMobile();
  const { closeModal } = useModal();
  const { teamPlaceColor, displayName } = useTeamPlace();

  const {
    schedule,
    times,
    isAllDay,
    isDescription,
    isDescriptionMaxLength,

    handlers: {
      handleScheduleChange,
      handleScheduleBlur,
      handleScheduleSubmit,
      handleStartTimeChange,
      handleEndTimeChange,
      handleIsAllDayChange,
      handleIsDescription,
      handleDescriptionInput,
    },
  } = useScheduleEditModal(scheduleId, initialSchedule);

  if (initialSchedule === undefined) {
    return null;
  }

  return (
    <Modal>
      <S.Backdrop onClick={closeModal} />
      <S.Container $calendarSize={calendarSize} $isMobile={isMobile}>
        <S.Header>
          <Button
            variant="plain"
            type="button"
            onClick={closeModal}
            css={S.closeButton}
            aria-label="닫기"
          >
            <CloseIcon />
          </Button>
        </S.Header>
        <form onSubmit={handleScheduleSubmit}>
          <S.TitleWrapper>
            <Input
              width="100%"
              height="100%"
              placeholder="일정 제목"
              css={S.title}
              name="title"
              value={schedule.title}
              required
              onChange={handleScheduleChange}
            />
          </S.TitleWrapper>

          <S.TimeSelectContainer $isMobile={isMobile}>
            <Text weight="semiBold">일정 시작</Text>
            <S.InputWrapper $isMobile={isMobile}>
              <Input
                width={isAllDay ? '100%' : '50%'}
                height="36px"
                type="date"
                css={S.dateTimeLocalInput}
                name="startDate"
                value={schedule.startDate}
                onChange={handleScheduleChange}
                onBlur={handleScheduleBlur}
                required
              />
              {!isAllDay && (
                <TimeTableMenu
                  displayValue={times.startTime}
                  onSelect={handleStartTimeChange}
                />
              )}
            </S.InputWrapper>
          </S.TimeSelectContainer>
          <S.TimeSelectContainer $isMobile={isMobile}>
            <Text weight="semiBold">일정 마감</Text>
            <S.InputWrapper $isMobile={isMobile}>
              <Input
                width={isAllDay ? '100%' : '50%'}
                height="36px"
                type="date"
                css={S.dateTimeLocalInput}
                name="endDate"
                value={schedule.endDate}
                min={schedule.startDate}
                onChange={handleScheduleChange}
                onBlur={handleScheduleBlur}
                required
              />
              {!isAllDay && (
                <TimeTableMenu
                  displayValue={times.endTime}
                  onSelect={handleEndTimeChange}
                />
              )}
            </S.InputWrapper>
          </S.TimeSelectContainer>
          <S.ConvenientContainer>
            <Switch
              checked={isAllDay}
              onChange={handleIsAllDayChange}
              onLabel={'종일'}
              offLabel={'종일'}
              onColor={theme.color.PRIMARY}
            />{' '}
            <p
              className="hidden"
              aria-live="assertive"
              aria-relevant="additions"
            >
              {isAllDay
                ? '종일 일정이 선택되었습니다.'
                : '종일 일정이 해제되었습니다.'}
            </p>
            <Button
              variant="plain"
              type="button"
              css={S.descriptionButton(isDescription)}
              onClick={handleIsDescription}
            >
              <Svg
                type="MemoIcon"
                size={18}
                fill={isDescription ? theme.color.WHITE : theme.color.PRIMARY}
              />
              <Text
                css={S.descriptionText(isDescription)}
                weight="semiBold"
                size="sm"
              >
                메모
              </Text>
            </Button>
          </S.ConvenientContainer>
          {isDescription && (
            <>
              <S.DescriptionTextarea
                rows={1}
                placeholder={`메모를 작성해주세요.(최대 ${SCHEDULE_DESCRIPTION_MAX_LENGTH}자)`}
                value={schedule.description}
                onChange={handleDescriptionInput}
              />
              <S.WarnDiv>
                {!isDescriptionMaxLength ? (
                  <Text size="xs">
                    ({schedule.description.length} /
                    {SCHEDULE_DESCRIPTION_MAX_LENGTH}자)
                  </Text>
                ) : (
                  <Text size="xs" css={S.errorText}>
                    최대 ${SCHEDULE_DESCRIPTION_MAX_LENGTH}자까지
                    입력가능합니다.
                  </Text>
                )}
              </S.WarnDiv>
            </>
          )}
          <S.InnerContainer>
            <S.TeamNameContainer title={displayName}>
              <TeamBadge teamPlaceColor={teamPlaceColor} size="lg" />
              {!isMobile && (
                <Text size="sm" css={S.teamPlaceName}>
                  {displayName}
                </Text>
              )}
            </S.TeamNameContainer>
            <S.ControlButtonWrapper>
              <Button variant="primary" css={S.submitButton}>
                수정
              </Button>
            </S.ControlButtonWrapper>
          </S.InnerContainer>
        </form>
      </S.Container>
    </Modal>
  );
};

export default ScheduleEditModal;
